"""Build evidence report with SVG overlays; raw camera images are unchanged."""
import json,math,html,xml.etree.ElementTree as ET
from pathlib import Path
OUT=Path(__file__).resolve().parents[1]/'optimization_reports/map10_lane_audit'
audit=json.loads((OUT/'audit.json').read_text(encoding='utf-8'));conflicts=json.loads((OUT/'line_conflicts.json').read_text(encoding='utf-8'));views={v['id']:v for v in json.loads((OUT/'views.json').read_text())}
meta=ET.parse(r'D:\carla\carla\Import\STORE\map10\map10.rrdata.xml').getroot()
yellow=next(e for e in meta.iter('Material') if e.findtext('Name')=='LaneMarkingYellow1_Marking')
evidence={'source_yellow_material':{e.tag:e.text for e in yellow},'yellow_mark_road_ids':sorted({r['road'] for r in audit['mark_records'] if r['mark'].get('color')=='yellow'}),'confirmed_conflicting_boundaries':[dict(junction=d['junction'],road=d['road'],lane=d['lane'],start=d['start'],end=d['end'],crossing_routes=d['crossing_routes']) for d in conflicts if d['junction'] in [53,232] and d['crossing_routes']]}
(OUT/'findings.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2),encoding='utf-8')
def overlay(jid,roads):
 view=views['j'+str(jid)];f=800/math.tan(math.radians(75/2))
 def point(p):return (800+(p[1]-view['y'])*f/(view['camera_z']-p[2]),800-(p[0]-view['x'])*f/(view['camera_z']-p[2]))
 def poly(ps):return ' '.join('%.2f,%.2f'%point(p) for p in ps)
 paths=json.loads((OUT/('junction'+str(jid)+'_paths.json')).read_text());items=[]
 for p in paths:
  if (p['road'],p['lane']) in roads:items.append(f'<polyline points="{poly(p["points"])}" fill="none" stroke="#00bff2" stroke-width="5"/>')
 ds=[d for d in conflicts if d['junction']==jid and d['crossing_routes']]
 for d in ds:
  items.append(f'<polyline points="{poly(d["edge"])}" fill="none" stroke="#ef3f55" stroke-width="5"/>')
  for hit in d['crossing_routes']:
   if (hit['road'],hit['lane']) in roads:
    x,y=point(hit['point']);items.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="11" fill="#ffcd41" stroke="#292d36" stroke-width="3"/>')
 return f'<div class="overlay"><svg viewBox="0 0 1600 1600" role="img" aria-label="路口 {jid} 的标线与路线叠加"><image href="j{jid}.png" width="1600" height="1600"/><g class="annotations">'+''.join(items)+'</g></svg></div>'
intro='''<header><div class="eyebrow">MAP10 · 车道线专项检查 · 2026-10-03</div><h1>确认 3 项标线问题，定位到材质和道路编号</h1><p>黄色线显示错误 · 十字路口实线贯穿 · T 形路口实线封住转弯通道</p><nav><a href="#yellow">① 黄线材质</a><a href="#cross">② 十字路口</a><a href="#tee">③ T 形路口</a><a href="#normal">未判为错误的情况</a></nav></header><main>
<section><h2>结论</h2><p>标线问题主要有两类：<b>画面颜色与地图语义不一致</b>，以及<b>路口内保留了与通行路线交叉的连续实线</b>。前一类可以从黄色标线材质入手；后一类需要同时修正标线网格和 XODR，单独改控制代码不能解决画面指引冲突。</p>
<table><tr><th>优先级 / 位置</th><th>问题</th><th>定位（CARLA 米）</th></tr><tr><td>高 · 地图共用黄色标线材质</td><td>原始黄色着色未进入 UE BaseColor</td><td>直观样例 road 12：(324, −660, 0.15)</td></tr><tr><td>高 · junction 53</td><td>两条实线贯穿十字路口，与横向路线相交</td><td>中心 (−1000, −298, 0)</td></tr><tr><td>高 · junction 232</td><td>支路开口处两条实线截断转弯引导</td><td>中心 (−1000, 243, 0)</td></tr></table>
<p class="note">本次仅检查并生成证据，未修改原地图、材质或 XODR。原场景预览保持运行。</p></section>'''
color='''<section id="yellow"><h2>① 黄色标线显示成白线：根因已定位</h2><div class="cols"><a href="local12.png" target="_blank"><img src="local12.png" alt="road 12 的双黄线在画面中显示为白色"><small>road 12 双向两车道：中间两条线实际显示为白色</small></a><div><h3>三份证据相互对应</h3><ol><li>XODR 的 road 12 / lane 0 标为 <code>solid solid</code>、<code>color=yellow</code>。</li><li>RoadRunner 元数据里，<code>LaneMarkingYellow1_Marking</code> 使用浅色纹理，并指定 <code>DiffuseColor=(1, 0.835294, 0)</code>。</li><li>UE 材质的 BaseColor 直接接入该浅色纹理，图中没有用于乘上黄色的节点。实拍与之吻合。</li></ol><p><b>根因：</b>黄色材质的颜色乘数没有体现在当前材质图中。不是仅靠曝光导致的错觉。</p><p><b>影响：</b>凡引用该材质的可见黄色标线都会受影响。XODR 中有 42 个道路 ID 含黄色标记定义；部分位于分隔带或其他几何下方，不能把 42 等同于逐处可见缺陷数量。</p><p><b>建议：</b>为黄色材质恢复正确的颜色调制，校准颜色空间与实际光照后再检查白/黄线对比。此项不需要改变道路几何或 waypoint。</p></div></div><p class="path">/Game/package/Maps/map10/LaneMarkingYellow1_Marking</p><p><a href="LaneMarkingYellow1_Marking.t3d">查看 UE 材质图文本</a> · <a href="line_materials.json">网格材质槽</a> · <a href="findings.json">原始颜色与问题坐标</a></p></section>'''
cross='''<section id="cross"><h2>② junction 53：实线连续穿过十字路口</h2><p><b>定位：</b>road 158 / lane −2 与 road 159 / lane +2 的外侧标线，s≈0～41.09 m。两条线分别在 X≈−993 和 X≈−1007，Y≈−319～−278。</p><p>实拍中的连续实线与 XODR 的 <code>solid</code> 一致，所以这是标线设计/导出内容的问题。横向直行 road 67、68，以及部分转弯道路，其车道中心线直接穿过这些实线。</p><label><input type="checkbox" checked onchange="this.closest('section').classList.toggle('raw',!this.checked)"> 显示测量叠加：红＝待调整实线；蓝＝实际 waypoint 路线；黄点＝相交位置</label>'''+overlay(53,[(67,2),(68,-2),(83,-1)])+'''<p><b>建议：</b>重新定义交叉口内这些边界的标线范围，在冲突区域取消连续禁止跨越实线，按实验道路设计补充必要的引导线。模型与 XODR 一起改；入口段标线需与停止线/人行横道位置协调。</p><p><a href="j53.png" target="_blank">打开未标注原图</a></p></section>'''
tee='''<section id="tee"><h2>③ junction 232：T 形路口支路开口被实线贯穿</h2><p><b>定位：</b>road 250 / lanes −2、−3，s≈0～33.50 m。两条线分别在 X≈−993 和 X≈−989.5，Y≈225～258。</p><p>这两条实线在支路开口前连续延伸。road 235、239、251、256 的转弯路线会与其中一条或两条线相交；可视标线与路口可通行路线产生冲突。</p><label><input type="checkbox" checked onchange="this.closest('section').classList.toggle('raw',!this.checked)"> 显示测量叠加：红＝待调整实线；蓝＝转弯 waypoint 路线；黄点＝相交位置</label>'''+overlay(232,[(235,1),(239,-1),(251,1)])+'''<p><b>建议：</b>优先处理支路开口对应的 road 250 两条边界，在转弯通道内断开/重做引导。另一方向还有连续实线，但本次没有检出它们与转弯中心线相交，不混作同样的已确认问题。</p><p><a href="j232.png" target="_blank">打开未标注原图</a></p></section>'''
normal='''<section id="normal"><h2>这些情况暂不判成车道线错误</h2><ul><li><b>高架 road 6、9、29 的渐变段：</b>有 5 条车道宽度逐渐接近 0；与相邻车道之间局部标为 NONE。俯视图和宽度变化一致，属于车道增减的渐变区域，不能仅凭“线消失”判定缺线。运动脚本需避免在极窄部分生成车辆。</li><li><b>路口内部没有线：</b>仅凭内部 roadMark=none 不能判错；需结合转弯路线和可见指引。</li><li><b>road 267：</b>之前确认的缺失车道连接仍然是导航拓扑问题，不能靠补画一条线修复。本报告没有把它充作第四项标线缺陷。</li></ul><div class="cols"><a href="taper29.png" target="_blank"><img src="taper29.png" alt="road 29 车道渐变"><small>road 29 收窄区</small></a><a href="taper9.png" target="_blank"><img src="taper9.png" alt="road 9 车道渐变"><small>road 9 渐变区</small></a></div></section>
<section><h2>覆盖范围与限制</h2><ul><li>解析全图 84 条道路的 688 条 roadMark 记录；在可驾驶车道上以约 2 m 间隔查询 33,177 个 waypoint。</li><li>检查全部 7 个路口，另外拍摄收窄段、普通直路、双向支路等，共 14 张 1600×1600 实拍图。</li><li>对非路口的相邻同向可驾驶车道，未检出“单/双实线却允许跨越”的 API 规则矛盾；2 m 续点检查也没有出现距离大于 3 m 或航向突变大于 25° 的记录。这不代表所有绘制细节都无误。</li><li>这是标线/路线一致性检查，不是交通法规合规认证，也没有穷尽每米路面的视觉检测。未测动态闪烁、所有远距离 LOD 或逐路段行车视角。</li><li>叠加采用实际相机内参、位置和 waypoint 投影；原始 PNG 未修改。线宽、圆点为显示效果，不表示测量误差。</li></ul><p><a href="audit.json">完整规则扫描</a> · <a href="line_conflicts.json">标线与路径相交数据</a> · <a href="views.json">相机位置</a> · <a href="cleanup.json">相机清理记录</a> · <a href="../map10_survey/index.html">区域图册</a></p>
<p>机制参考：<a href="https://carla.readthedocs.io/en/0.9.15/core_map/">CARLA Maps and navigation</a>。上述缺陷结论来自本机实际 XODR、UE 材质导出和相机画面。</p><details><summary>全部实拍图</summary><div class="gallery">'''
for key in views:normal+=f'<a href="{key}.png" target="_blank"><img src="{key}.png" loading="lazy" alt="{key}"><small>{key}</small></a>'
normal+='</div></details></section></main><footer>map10 · 只读检查 · 原始地图保持不变</footer>'
style='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>map10 车道线问题检查</title><style>*{box-sizing:border-box}body{margin:0;background:#f2f5f8;color:#21354a;font:16px/1.8 'Microsoft YaHei',sans-serif}header{background:#172d42;color:#fff;padding:42px max(24px,calc((100vw - 1160px)/2))}h1{font-size:32px;line-height:1.5}.eyebrow,header p{color:#bcd0e0}nav{display:flex;gap:22px;flex-wrap:wrap}nav a{color:#c1e3ff}main{max-width:1200px;padding:20px;margin:auto}section{background:white;margin:20px 0;padding:28px;border:1px solid #dbe3eb;border-radius:12px;scroll-margin-top:16px}a{color:#20699c;text-decoration:none}a:hover{text-decoration:underline}h2{font-size:26px}h3{font-size:20px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:12px;border-bottom:1px solid #dbe3eb;vertical-align:top}th{background:#f3f6f9}.cols{display:grid;grid-template-columns:1fr 1fr;gap:24px}img{width:100%;display:block;border-radius:7px}small,.note{color:#64788b}.path,code{overflow-wrap:anywhere;font-family:Consolas,'Microsoft YaHei',monospace}.path{background:#f1f5f8;padding:12px}.overlay{max-width:880px;margin:18px auto}.overlay svg{width:100%;display:block;border-radius:8px}.raw .annotations{display:none}label{display:block;background:#eaf3f9;padding:12px;cursor:pointer}input{accent-color:#20749d}li{margin:10px 0}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}footer{text-align:center;padding:24px;color:#72869b}@media(max-width:800px){.cols{grid-template-columns:1fr}section{padding:18px}h1{font-size:26px}.gallery{grid-template-columns:1fr 1fr}}</style></head><body>'''
(OUT/'index.html').write_text(style+intro+color+cross+tee+normal+'</body></html>',encoding='utf-8')
print(OUT/'index.html')
